    <a class="skip-link" href="#main-content">Skip to main content</a>
    <main id="main-content" tabindex="-1">
      <section class="support-card" aria-labelledby="support-form-title">
        <h1 id="support-form-title">Contact support</h1>
        <p class="intro">
          Share your details below and our support team will follow up as soon as possible.
        </p>
        <p class="required-note">Fields marked <span class="required-mark">*</span> are required.</p>

        <form id="support-form" novalidate>
          <div class="form-field">
            <label for="full-name">Full name <span class="required-mark" aria-hidden="true">*</span></label>
            <input
              id="full-name"
              name="fullName"
              type="text"
              autocomplete="name"
              required
              aria-describedby="full-name-error"
            />
            <p id="full-name-error" class="error-message" aria-live="polite"></p>
          </div>

          <div class="form-field">
            <label for="email">Email address <span class="required-mark" aria-hidden="true">*</span></label>
            <input
              id="email"
              name="email"
              type="email"
              inputmode="email"
              autocomplete="email"
              required
              aria-describedby="email-error"
            />
            <p id="email-error" class="error-message" aria-live="polite"></p>
          </div>

          <div class="form-field">
            <label for="phone">Phone number</label>
            <input
              id="phone"
              name="phone"
              type="tel"
              inputmode="tel"
              autocomplete="tel"
              aria-describedby="phone-help phone-error"
            />
            <p id="phone-help" class="helper-text">Expected format: +1 555-123-4567 or (555) 123-4567.</p>
            <p id="phone-error" class="error-message" aria-live="polite"></p>
          </div>

          <button type="submit">Send support request</button>
          <p id="form-status" class="status-message" aria-live="polite"></p>
        </form>
      </section>
    </main>

    <script>
      const form = document.getElementById("support-form");
      const formStatus = document.getElementById("form-status");
      const fields = {
        fullName: {
          input: document.getElementById("full-name"),
          error: document.getElementById("full-name-error"),
          validate(value) {
            if (!value.trim()) {
              return "Error: Enter your full name.";
            }

            return "";
          },
        },
        email: {
          input: document.getElementById("email"),
          error: document.getElementById("email-error"),
          validate(value) {
            if (!value.trim()) {
              return "Error: Enter your email address.";
            }

            const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
            if (!emailPattern.test(value.trim())) {
              return "Error: Enter a valid email address, like name@example.com.";
            }

            return "";
          },
        },
        phone: {
          input: document.getElementById("phone"),
          error: document.getElementById("phone-error"),
          validate(value) {
            const trimmedValue = value.trim();
            if (!trimmedValue) {
              return "";
            }

            const phonePattern = /^\+?[\d\s().-]{10,20}$/;
            const digits = trimmedValue.replace(/\D/g, "");

            if (!phonePattern.test(trimmedValue) || digits.length < 10 || digits.length > 15) {
              return "Error: Enter a phone number in the expected format.";
            }

            return "";
          },
        },
      };

      function setFieldError(fieldConfig, message) {
        fieldConfig.error.textContent = message;
        fieldConfig.input.setAttribute("aria-invalid", message ? "true" : "false");
      }

      function validateField(fieldConfig) {
        const message = fieldConfig.validate(fieldConfig.input.value);
        setFieldError(fieldConfig, message);
        return message;
      }

      Object.values(fields).forEach((fieldConfig) => {
        fieldConfig.input.addEventListener("input", () => {
          validateField(fieldConfig);
          if (formStatus.textContent) {
            formStatus.textContent = "";
          }
        });

        fieldConfig.input.addEventListener("blur", () => {
          validateField(fieldConfig);
        });
      });

      form.addEventListener("submit", (event) => {
        event.preventDefault();
        formStatus.textContent = "";

        const invalidFields = Object.values(fields).filter((fieldConfig) => validateField(fieldConfig));

        if (invalidFields.length > 0) {
          invalidFields[0].input.focus();
          formStatus.textContent = "Please correct the errors in the form.";
          return;
        }

        formStatus.textContent = "Your support request is ready to send.";
        form.reset();
        Object.values(fields).forEach((fieldConfig) => {
          setFieldError(fieldConfig, "");
        });
      });
    </script>
  </body>
</html>
