             const trimmedValue = value.trim();
             if (!trimmedValue) {
               return "";
             }

             const phonePattern = /^\+?[\d\s().-]{10,20}$/;
             const digits = trimmedValue.replace(/\D/g, "");

             if (!phonePattern.test(trimmedValue) || digits.length < 10 || digits.length > 15) {
               return "Error: Enter a phone number in the expected format.";
             }

             return "";
           },
         },
